using EventLensAI.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace EventLensAI.Infrastructure.Persistence.Configurations;
internal sealed class CaptureConfigurationConfiguration:IEntityTypeConfiguration<CaptureConfiguration>
{public void Configure(EntityTypeBuilder<CaptureConfiguration>b){b.ToTable("capture_configurations");b.ConfigureBase();b.Property(x=>x.ImageQuality).HasPrecision(4,3);b.Property(x=>x.Resolution).HasMaxLength(20);b.HasIndex(x=>new{x.OrganizationId,x.EventId}).IsUnique().HasFilter("[IsDeleted] = 0");b.HasOne<Organization>().WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Event>().WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class CapturedPhotoConfiguration:IEntityTypeConfiguration<CapturedPhoto>
{public void Configure(EntityTypeBuilder<CapturedPhoto>b){b.ToTable("captured_photos");b.ConfigureBase();b.Property(x=>x.FileName).HasMaxLength(255);b.Property(x=>x.FilePath).HasMaxLength(500);b.Property(x=>x.MimeType).HasMaxLength(100);b.Property(x=>x.ProcessingStatus).HasConversion<string>().HasMaxLength(30);b.HasIndex(x=>x.SessionId);b.HasIndex(x=>x.EventId);b.HasIndex(x=>x.CapturedAt);b.HasIndex(x=>x.ProcessingStatus);b.HasIndex(x=>new{x.SessionId,x.CaptureNumber});b.HasOne<Organization>().WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Event>().WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.Restrict);b.HasOne<BoothSession>().WithMany().HasForeignKey(x=>x.SessionId).OnDelete(DeleteBehavior.Restrict);}}
